// @ts-nocheck
/**
 * PuchoAI Unified Code Tool — Centralized Metadata Parser, Duration Calculator & Taxonomy Reference
 * 
 * 1. Parses filename segment structure to extract metadata.
 * 2. Parses STT output payload to extract duration_seconds and divides into minutes & seconds.
 * 3. Checks validity / non-contact condition to determine if call should be processed ("Yes" or "No").
 * 4. Returns parsed metadata, duration metrics, transcript, validation flags, and hardcoded Taxonomy object.
 */

const TAXONOMY = {
  version: "2.0",
  generated: new Date().toISOString(),

  final_classifications: [
    "intent",
    "query",
    "complaint",
    "non-contact",
