    VIRTUAL: {
      name: "VIRTUAL",
      full_name: "Prudent",
      greeting_standard: '"Good morning/afternoon, this is [Name] from Prudent. How may I assist you?"',
      core_topics: [
        "SIP", "KYC", "Redemption", "Account Management", "General Inquiry"
      ]
    }
  },

  call_topics: {
    inbound: [
      "KYC", "SIP", "Redemption", "Mandate", "eMandate",
      "Login/OTP", "ARN", "Portfolio", "Liquiloan",
      "Stock Broking", "Account Management", "General Inquiry",
      "Complaint", "Other Products", "Other"
    ],
    outbound: [
      "SIP Review", "Mandate Follow-up", "Missed Payment",
      "ARN Renewal", "KYC Completion", "Lapsed SIP",
      "Campaign Outreach", "Virtual RM Advisory",
      "Lead Follow-up", "Upsell/Cross-sell"
    ],
    rules: {
      complaint_topic_note: "Use call_topic=Complaint only when no specific subject domain is identifiable",
      other_products_note: "Financial domain but outside campaign core scope — preferred fallback",
      other_note: "Topic cannot be identified at all — use only as last resort"
    }
  },

  call_topic_boundary_rules: {
    description: "Before assigning call_topic, ask yourself in this order:",
    steps: [
      "1. Is the call clearly and primarily about one of the core topics listed above for the campaign? → use that topic.",
      "2. Is it clearly about a different campaign's well-defined topic (e.g. \"Stock Broking\" for equity trading, \"Liquiloan\" for a loan product) that happened to come in on this line? → use that specific topic.",
      "3. Is the call about something outside both lists — any financial product, service, or query not clearly covered by the standard campaign taxonomy? → call_topic=Other Products, call_sub_topic=the specific product or service the customer is discussing."
    ],
    principle: "\"Other Products\" is the principled default for any call that concerns a product, service, or topic outside the campaign's core scope. This includes any product you have not seen in the taxonomy before. Do NOT force-map an unrecognised topic to the closest-sounding existing topic — that is the incorrect fallback this rule is designed to prevent."
  },

  kpi11_intents: {
    inbound: [
      "Complaint",
