    ],
    rules: {
      instruction: "Use EXACTLY one label from the taxonomy above. Copy character-for-character. Do not paraphrase, abbreviate, or invent labels.",
      kpi11_intent_detail: "one-sentence explanation of what the customer actually needed or did.",
      kpi11_sub_category: "a 2-4 word label one level narrower than kpi11_intent (e.g., 'SIP pause request', 'mandate bank failure', 'KYC document query'). Not a full sentence."
    },
    classification_mapping: {
      "General Information": "intent",
      "Callback Request": "intent",
      "SIP Start": "intent",
