      "Mandate Follow-up": "intent",
      "Missed Payment": "intent",
      "ARN Renewal": "intent",
      "KYC Completion": "intent",
      "Lapsed SIP": "intent",
      "Campaign Outreach": "intent",
      "Virtual RM Advisory": "intent",
      "Lead Follow-up": "intent",
      "Upsell/Cross-sell": "intent"
    }
  },

  kyc_question_types: [
    { value: "why_kyc",        label: "Customer asking why KYC is required or mandatory" },
    { value: "about_process",   label: "Questions about how to complete KYC, documents needed, or steps involved" },
    { value: "document_submission", label: "Call where documents are being submitted, uploaded, or confirmed" },
    { value: "verification",    label: "KYC status check, verification pending/rejected, or re-KYC issues" },
    { value: "null",            label: "Not applicable — call is not KYC-related" }
  ],

  classification_signals: {
