        "error", "issue", "status", "tat", "delayed",
        "nahi aaya", "kab aayega", "kyu nahi"
      ]
    },
    complaint: {
      english: [
        "complaint", "grievance", "dissatisf", "escalat",
        "churn", "frustrated", "angry", "wrong charges",
        "wrong nav", "deducted wrongly", "financial loss",
        "fraud", "sebi", "poor service", "unacceptable"
