      hindi_urdu: [
        "shikayat", "narazgi", "farayad", "phariyaad",
        "gussa", "galat kaat liya", "wapas nahi aaya"
      ]
    }
  },

  validity_tiers: [
    {
      tier: 0,
      name: "NON-CONTACT",
      description: "Only telecom automation (switched off / not reachable / voicemail). Zero human speech.",
      rules: {
        evaluation: "all sop=NA, kpi1=No, kpi2=No, kpi3=Efficient, kpi4=No, kpi5=NA, kpi6=3, kpi9=NA, coaching=Green, risk=None, ztp=No, classification=non-contact, tier=0"
      }
    },
    {
      tier: 1,
      name: "DISCONNECT",
      description: "Agent connected but line dropped before any customer query, concern, or actionable topic was raised. No meaningful exchange occurred.",
      rules: {
        evaluation: "all sop=NA, kpi1=No, kpi3=Efficient, kpi4=No, kpi6=3, kpi9=NA, coaching=Green, risk=None, ztp=No, classification=invalid, tier=1",
        note: "Agent not at fault. Line drop = telecom event. No SOP degrade, no risk flag, no ZTP, coaching stays Green."
      }
    },
    {
      tier: 2,
      name: "HOLD-DROP",
      description: "Caller disconnected while queued or on hold before the interaction could complete.",
      rules: {
        gate_check: "Did a meaningful customer interaction (query raised, issue discussed, topic exchanged) actually occur before the hold event? If NO, all sop=NA. If YES, evaluate sop_greeting + sop_caller_identified from pre-hold content only; all other sop=NA.",
        evaluation: "kpi4=No (hold disconnect ≠ abandonment), kpi6=3, kpi9=NA, coaching=Green, risk=None, ztp=No, classification=invalid, tier=2",
        note: "Customer leaving hold is their choice, not agent abandonment. No risk or ZTP flags regardless of hold duration."
      }
    },
    {
      tier: 3,
      name: "NOISE",
      description: "Third-party or background audio dominates. No clear agent-customer exchange.",
      rules: {
        evaluation: "all sop=NA, kpi6=3, kpi9=NA, coaching=Green, risk=None, ztp=No, classification=invalid, tier=3",
        note: "Third-party audio cannot be attributed to the agent. Never set risk or ZTP from background voices — even if the noise resembles a ZTP event."
      }
    },
    {
      tier: 4,
      name: "NON-EVALUABLE",
      description: "Blank transcript, content consists only of greetings/filler with no customer query or topic raised, or language is unrecognised.",
      rules: {
        evaluation: "all sop=NA, kpi6=3, kpi9=NA, coaching=Green, risk=None, ztp=No, classification=invalid, tier=4"
      }
    },
    {
      tier: 5,
      name: "VALID",
      description: "Meaningful agent-customer exchange present. Proceed with full evaluation.",
      rules: {
        evaluation: "Evaluate all SOPs and KPIs normally."
      }
    }
  ],

  non_contact_signal_phrases: [
    "switched off", "not reachable", "not available",
    "please try again", "out of coverage", "out of service",
    "the number you have dialed", "subscriber you are calling",
    "leave a message after the tone", "voicemail",
    "this number is not in service", "currently busy",
    "व्यस्त है", "आपका कॉल", "जो नंबर आपने डायल", "जो नम्बर आपने",
    "इस समय उपलब्ध नहीं", "स्विच्ड ऑफ", "नेटवर्क से बाहर",
    "હાલ ઉપલબ્ધ નથી", "સ્વીચ ઑફ"
  ],

  greeting_standards: {
    PLC:     '"Good morning/afternoon, this is [Name] from Prudent Loyalty Club. How may I assist you?"',
    NONPLC:  '"Good morning/afternoon, this is [Name] from Prudent / Fundzbazar. How may I assist you?"',
    BROKING: '"Good morning/afternoon, this is [Name] from Prudent Stock Broking. How may I assist you?"',
    VIRTUAL: '"Good morning/afternoon, this is [Name] from Prudent. How may I assist you?"'
  },

  sop_rules: {
    sop_1_greeting: {
      label: "SOP 1 — Greeting",
      valid_values: ["Yes", "No", "NA"],
      description: "Agent's opening contains recognisable structural greeting intent."
    },
    sop_2_caller_identified: {
      label: "SOP 2 — Caller Identified",
      valid_values: ["Yes", "No", "NA"],
      special: "DealerDesk/Partner lines = system-verified at connect, mark YES automatically."
    },
    sop_3_hold_permission: {
      label: "SOP 3 — Hold Permission",
      valid_values: ["Yes", "No", "NA"]
    },
    sop_4_hold_refresh: {
      label: "SOP 4 — Hold Refresh",
      valid_values: ["Yes", "No", "NA"]
    },
    sop_5_closing: {
      label: "SOP 5 — Closing",
      valid_values: ["Yes", "No", "NA"]
    },
    sop_6_feedback_ivr: {
      label: "SOP 6 — Feedback IVR",
      valid_values: ["Yes", "No", "NA"]
    },
    sop_7_behaviour: {
      label: "SOP 7 — Behaviour",
      valid_values: ["Yes", "No", "NA"]
    }
  },

  kpi_rules: {
    kpi1_resolution: { label: "KPI 1 — Call Resolution", valid_values: ["Yes", "No", "Partial", "NA"] },
    kpi2_fcr: { label: "KPI 2 — First Call Resolution", valid_values: ["Yes", "No", "Unknown", "NA"] },
    kpi3_aht: { label: "KPI 3 — AHT Efficiency", valid_values: ["Efficient", "Acceptable", "Inefficient"] },
    kpi4_abandonment: { label: "KPI 4 — Call Abandonment", valid_values: ["Yes", "No", "NA"] },
    kpi5_csat: { label: "KPI 5 — CSAT Indicator", valid_values: ["High", "Medium", "Low", "NA"] },
    kpi6_quality: { label: "KPI 6 — Call Quality Score", valid_values: [1, 2, 3, 4, 5] },
    kpi7_hold_compliance: { label: "KPI 7 — Hold Compliance", valid_values: ["Compliant", "Non-Compliant", "NA"] },
    kpi8_ivr_transfer: { label: "KPI 8 — IVR Transfer", valid_values: ["Yes", "No", "Customer Refused", "NA"] },
    kpi9_process_adherence: { label: "KPI 9 — Process Adherence", valid_values: ["Full", "Partial", "None", "NA"] },
    kpi10_escalation: { label: "KPI 10 — Escalation", valid_values: ["Yes", "No", "NA"] },
    kpi11_intent: { label: "KPI 11 — Intent" },
    kpi12_service_level: { label: "KPI 12 — Service Level", default: "Requires Telephony Data" },
    kpi13_repeat_call: { label: "KPI 13 — Repeat Call", default: "Requires CRM Data" },
    kpi14_query_raised: { label: "KPI 14 — Query Raised", valid_values: ["Yes", "No", "NA"] },
    kpi15_sentiment: { label: "KPI 15 — Sentiment" }
