export const code = async (inputs) => {

  const getTranscriptText = (data) => {
    if (!data) return "";
    let parsed = data;
    if (typeof data === 'string') {
      try { parsed = JSON.parse(data); } catch(e) {}
    }
    if (parsed && typeof parsed === 'object') {
      if (parsed.response) {
        let resp = parsed.response;
        if (typeof resp === 'string') {
          try { resp = JSON.parse(resp); } catch(e) {}
        }
        if (resp && typeof resp === 'object' && resp.text) return resp.text;
        if (typeof resp === 'string') return resp;
      }
      if (parsed.text) return parsed.text;
    }
    return typeof data === 'string' ? data : JSON.stringify(data);
  };

  const transcript = getTranscriptText(inputs.transcript).trim();

  // Extract trigger object safely for bracket notation access in Pucho AI TS environment
  let trigger = inputs.trigger || {};
  if (typeof trigger === 'string') {
    try { trigger = JSON.parse(trigger); } catch(e) { trigger = {}; }
  }
  const body = trigger['body'] || trigger || {};

  // Extract initial fields from inputs or trigger
  const filename = inputs.filename || body['filename'] || trigger['filename'] || "";

  // temporary parse variables
  let parsedCallDate = "";
  let parsedMobileNumber = "";
  let parsedAgentCode = "";
  let parsedCampaign = "";

  // 1. Filename parsing segment logic (if filename is present)
  if (filename) {
    const match = filename.match(/^(\d{8})-(\d+)_(\d+)_([^_]+)_([^-._]+)/);
    if (match) {
      const rawDate = match[1];
      parsedCallDate = `${rawDate.substring(0, 4)}-${rawDate.substring(4, 6)}-${rawDate.substring(6, 8)}`;
      parsedMobileNumber = match[3];
      parsedAgentCode = match[4]; // Segment 4 is agent code
      parsedCampaign = match[5].toUpperCase();
    }
  }

  // 2. Prioritize filename values, but if empty, fall back to webhook trigger inputs
  let agentCode = parsedAgentCode || inputs.agent_code || body['agent_code'] || trigger['agent_code'] || "";
  let mobileNumber = parsedMobileNumber || inputs.mobile_number || body['mobile_number'] || trigger['mobile_number'] || "";
  let callDate = parsedCallDate || inputs.call_date || body['call_date'] || trigger['call_date'] || "";
  let campaign = (parsedCampaign || inputs.campaign || body['campaign'] || trigger['campaign'] || "NONPLC").toUpperCase();

  // Resolve agent name using dynamic Supabase DB API / inputs.supabase (and fallback mapping / code default)
  let agentName = inputs.agent_name || body['agent_name'] || trigger['agent_name'] || "";

  if (!agentName && agentCode) {
    // 1. Try to fetch from the passed supabase input (output of Search Rows step)
    let dbAgents = inputs.supabase;
    if (typeof dbAgents === 'string') {
      try { dbAgents = JSON.parse(dbAgents); } catch (e) {}
    }
    if (Array.isArray(dbAgents) && dbAgents.length > 0) {
      const foundAgent = dbAgents.find(a => String(a.agent_code) === String(agentCode));
      if (foundAgent && foundAgent.agent_name) {
        agentName = foundAgent.agent_name;
      } else if (dbAgents[0] && dbAgents[0].agent_name) {
        // Fallback: If Search Rows was already filtered by agentCode, first index is correct
        agentName = dbAgents[0].agent_name;
      }
    }

    // 2. Fallback to direct fetch query if not resolved from inputs.supabase
    if (!agentName) {
      const supabaseUrl = '';
      const supabaseAnonKey = '';

      try {
        const dbResponse = await fetch(`${supabaseUrl}/rest/v1/agents?agent_code=eq.${agentCode}&select=agent_name`, {
          headers: {
            'apikey': supabaseAnonKey,
            'Authorization': `Bearer ${supabaseAnonKey}`
          }
        });
        if (dbResponse.ok) {
          const dbData = await dbResponse.json();
          if (dbData && dbData.length > 0) {
            agentName = dbData[0].agent_name;
          }
        }
      } catch(e) {
        // Revert to local mapping fallback
      }
    }

    // 3. Fallback to hardcoded map or default name
    if (!agentName) {
      agentName = AGENT_NAMES_MAP[agentCode] || `Agent ${agentCode}`;
    }
  }

  if (!callDate) {
    callDate = new Date().toISOString().split('T')[0];
  }

  // ─── DURATION PARSING & MINUTES/SECONDS DIVISION ───
  let rawDuration = 0;
  const extractDuration = (src) => {
    if (!src) return 0;
    let parsed = src;
    if (typeof src === 'string') {
      try { parsed = JSON.parse(src); } catch(e) {}
    }
    if (parsed && typeof parsed === 'object') {
      if (parsed.data && parsed.data.response && parsed.data.response.duration_seconds !== undefined) {
        return Number(parsed.data.response.duration_seconds) || 0;
      }
      if (parsed.response && parsed.response.duration_seconds !== undefined) {
        return Number(parsed.response.duration_seconds) || 0;
      }
      if (parsed.duration_seconds !== undefined) {
        return Number(parsed.duration_seconds) || 0;
      }
      if (parsed.duration !== undefined) {
        return Number(parsed.duration) || 0;
      }
    }
    return 0;
  };

  rawDuration = extractDuration(inputs.STT) || 
                extractDuration(inputs.stt) || 
                extractDuration(inputs.trigger) || 
                Number(inputs.duration_seconds || inputs.duration_sec || body['duration_seconds'] || body['duration'] || 0);

  const durationSeconds = Math.round(rawDuration);
  const minutes = Math.floor(durationSeconds / 60);
  const seconds = durationSeconds % 60;
  const durationFormatted = `${minutes} min ${seconds} sec`;
  const durationFormattedMMSS = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  // ─── VALIDATION CONDITION CHECK (Process Forward: Yes / No) ───
  const NON_CONTACT_SIGNALS = [
    "switched off", "not reachable", "not available",
    "please try again", "out of coverage", "out of service",
    "the number you have dialed", "subscriber you are calling",
    "leave a message after the tone", "voicemail",
    "this number is not in service", "currently busy",
    "व्यस्त है", "आपका कॉल", "जो नंबर आपने डायल", "जो नम्बर आपने",
    "इस समय उपलब्ध नहीं", "स्विच्ड ऑफ", "नेटवर्क से बाहर",
    "હાલ ઉપલબ્ધ નથી", "સ્વીચ ઑફ"
  ];

  const wordCount = transcript ? transcript.split(/\s+/).filter(w => w.length > 0).length : 0;
  const transcriptLower = transcript.toLowerCase();

  let shouldProcess = "Yes";
  let reason = "Valid transcript detected — proceed with full LLM analysis.";

  if (!transcript || wordCount < 5) {
    shouldProcess = "No";
    reason = "Empty or too-short transcript — skip LLM processing.";
  } else {
    const isNonContact = NON_CONTACT_SIGNALS.some(phrase => transcriptLower.includes(phrase));
    if (wordCount < 60 && isNonContact) {
      shouldProcess = "No";
      reason = "Non-contact attempt detected (telecom automation / voicemail / IVR message) — skip LLM analysis.";
    }
  }


  // ─── V2: the organisation's own rules (Company Profile → company_context). Empty = the built-in taxonomy above. ───
  const CTX = (body && typeof body['company_context'] === 'object') ? body['company_context'] : null;
  let company_rules_text = '';
  let company_name = '';
  if (CTX) {
    company_name = CTX.company_name || '';
    if (Array.isArray(CTX.campaigns) && CTX.campaigns.length) {
      TAXONOMY.campaigns = Object.fromEntries(CTX.campaigns.map(c => [String(c.name).toUpperCase(), { name: c.name, full_name: c.full_name || c.name, greeting_standard: c.greeting_standard || '', core_topics: c.core_topics || [], direction: c.direction }]));
    }
    const list = (title, rows, f) => (Array.isArray(rows) && rows.length) ? '\n' + title + '\n' + rows.map(f).join('\n') : '';
    company_rules_text = [
      'Organisation: ' + company_name + (CTX.industry ? ' (' + CTX.industry + ')' : '') + (CTX.company_description ? ' — ' + CTX.company_description : ''),
      'AHT target: ' + (CTX.aht_target_min || 5) + ' minutes.',
      list('SOPs (score SOP 1..N in this order; NA rules as stated):', CTX.sops, (s, i) => 'SOP ' + (i + 1) + ' ' + s.title + ' | ' + (s.rule || '') + (s.na_rule ? ' | NA: ' + s.na_rule : '')),
      list('KPIs:', CTX.kpis, k => k.code + ' ' + k.title + ': ' + (k.rule || '') + (k.scale ? ' [' + k.scale + ']' : '')),
