  const sopFields = ['sop_greeting', 'sop_caller_identified', 'sop_hold_permission', 'sop_hold_refresh', 'sop_closing_script', 'sop_feedback_ivr', 'sop_no_behaviour_issue'];
  let sopScore = 0;
  for (const f of sopFields) {
    if (parsed[f] === 'Yes') sopScore++;
  }

  // Compute individual KPI Scores
  const kpi1Score = parsed.kpi1_call_resolution === 'Yes' ? 100 : parsed.kpi1_call_resolution === 'Partial' ? 60 : parsed.kpi1_call_resolution === 'NA' ? 80 : 0;
  const kpi2Score = parsed.kpi2_fcr === 'Yes' ? 100 : parsed.kpi2_fcr === 'Unknown' ? 60 : 0;
  const kpi3Score = parsed.kpi3_aht_efficiency === 'Efficient' ? 100 : parsed.kpi3_aht_efficiency === 'Acceptable' ? 70 : 30;
  const kpi4Score = parsed.kpi4_call_abandonment === 'No' ? 100 : 0;
  const kpi5Score = parsed.kpi5_csat_indicator === 'High' ? 100 : parsed.kpi5_csat_indicator === 'Medium' ? 60 : 30;
  const kpi14Score = parsed.kpi14_query_raised === 'Yes' ? 100 : parsed.kpi14_query_raised === 'NA' ? 80 : 50;

  // Calculate average KPI Score
  const kpiScore = Math.round((kpi1Score + kpi2Score + kpi3Score + kpi4Score + kpi5Score + kpi14Score) / 6);

  // Format sop_results as an ARRAY of objects (expected by dashboard compliance page)
  const sopResultsArray = [
    {
      sop_id: 1,
      name: "Professional Greeting",
      result: parsed.sop_greeting === "Yes" ? "Pass" : parsed.sop_greeting === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_greeting_note || "",
      ztp_violation: false
    },
    {
      sop_id: 2,
      name: "Caller Identified",
      result: parsed.sop_caller_identified === "Yes" ? "Pass" : parsed.sop_caller_identified === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_caller_identified_note || "",
      ztp_violation: false
    },
    {
      sop_id: 3,
      name: "Hold Permission",
      result: parsed.sop_hold_permission === "Yes" ? "Pass" : parsed.sop_hold_permission === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_hold_permission_note || "",
      ztp_violation: false
    },
    {
      sop_id: 4,
      name: "Hold Refresh",
      result: parsed.sop_hold_refresh === "Yes" ? "Pass" : parsed.sop_hold_refresh === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_hold_refresh_note || "",
      ztp_violation: false
    },
    {
      sop_id: 5,
      name: "Closing Script",
      result: parsed.sop_closing_script === "Yes" ? "Pass" : parsed.sop_closing_script === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_closing_script_note || "",
      ztp_violation: false
    },
    {
      sop_id: 6,
      name: "Feedback IVR",
      result: parsed.sop_feedback_ivr === "Yes" ? "Pass" : parsed.sop_feedback_ivr === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_feedback_ivr_note || "",
      ztp_violation: false
    },
    {
      sop_id: 7,
      name: "No Behaviour Issue",
      result: parsed.sop_no_behaviour_issue === "Yes" ? "Pass" : parsed.sop_no_behaviour_issue === "NA" ? "NA" : "Fail",
      confidence: 1,
      note: parsed.sop_no_behaviour_issue_note || "",
      ztp_violation: parsed.ztp_violation === "Yes"
    }
  ];

  // Format kpi_results as an ARRAY of objects (expected by dashboard CallDetailView)
  const kpiResultsArray = [
    {
      kpi_id: 1,
      name: "Call Resolution",
      value: parsed.kpi1_call_resolution || "No",
      score: kpi1Score,
      note: parsed.kpi1_note || ""
    },
    {
      kpi_id: 2,
      name: "First Call Resolution",
      value: parsed.kpi2_fcr || "No",
      score: kpi2Score,
      note: parsed.kpi2_note || ""
    },
    {
      kpi_id: 3,
      name: "AHT Efficiency",
      value: parsed.kpi3_aht_efficiency || "Inefficient",
      score: kpi3Score,
      note: parsed.kpi3_note || ""
    },
    {
      kpi_id: 4,
      name: "Call Abandonment",
      value: parsed.kpi4_call_abandonment || "No",
      score: kpi4Score,
      note: parsed.kpi4_note || ""
    },
    {
      kpi_id: 5,
      name: "CSAT Indicator",
      value: parsed.kpi5_csat_indicator || "Low",
      score: kpi5Score,
      note: parsed.kpi5_note || ""
    },
    {
      kpi_id: 6,
      name: "Call Quality Score",
      value: parsed.kpi6_call_quality_score || 3,
      score: (parsed.kpi6_call_quality_score || 3) * 20,
      note: parsed.kpi6_note || ""
    },
    {
      kpi_id: 7,
      name: "Hold Compliance",
      value: parsed.kpi7_hold_compliance || "NA",
      score: parsed.kpi7_hold_compliance === 'Compliant' ? 100 : 0,
      note: parsed.kpi7_note || ""
    },
    {
      kpi_id: 8,
      name: "IVR Transfer",
      value: parsed.kpi8_transfer_to_ivr || "NA",
      score: parsed.kpi8_transfer_to_ivr === 'Yes' ? 100 : 0,
      note: parsed.kpi8_note || ""
    },
    {
      kpi_id: 9,
      name: "Process Adherence",
      value: parsed.kpi9_process_adherence || "None",
      score: parsed.kpi9_process_adherence === 'Full' ? 100 : parsed.kpi9_process_adherence === 'Partial' ? 60 : 0,
      note: parsed.kpi9_note || ""
    },
    {
      kpi_id: 10,
      name: "Escalation",
      value: parsed.kpi10_escalated || "No",
      score: parsed.kpi10_escalated === 'No' ? 100 : 0,
      note: parsed.kpi10_note || ""
    },
    {
      kpi_id: 11,
      name: "Call Intent",
      value: callTopic, // Dynamic resolved topic
      call_classification: callCategory, // Dynamic resolved classification
      score: 100,
      note: parsed.kpi11_intent_detail || ""
    },
    {
      kpi_id: 12,
      name: "Service Level",
      value: parsed.kpi12_service_level || "Requires Telephony Data",
      score: null,
      note: "Cannot determine from transcript."
    },
    {
      kpi_id: 13,
      name: "Repeat Call",
      value: parsed.kpi13_repeat_call || "Requires CRM Data",
      repeat_call_signal: parsed.repeat_call_signal === 'Yes',
      score: null,
      note: parsed.repeat_call_signal === 'Yes' ? "Repeat call signal detected." : "No repeat call signals found."
    },
    {
      kpi_id: 14,
      name: "Query Raised",
      value: parsed.kpi14_query_raised || "No",
      score: kpi14Score,
      note: parsed.kpi14_note || ""
    },
    {
      kpi_id: 15,
      name: "Customer & Agent Sentiment",
      customer_sentiment: parsed.kpi15_customer_sentiment || "Neutral",
      agent_sentiment: parsed.kpi15_agent_sentiment || "Professional",
      score: 100,
      note: parsed.kpi15_sentiment_detail || ""
    }
  ];

  const now = new Date().toISOString();
  const callId = 'call_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);

  // Parse duration to MM:SS format
  const mm = Math.floor(durationSec / 60);
  const ss = Math.round(durationSec % 60);
  const durationStr = codeTool.duration_mmss || `${String(mm).padStart(2, '0')}:${String(ss).padStart(2, '0')}`;

  // Get correct audio URL
  const audioUrl = fileDetails.publicUrl || fileDetails.public_url || fileDetails.audio_url || codeTool.audio_url || triggerBody['audio_url'] || trigger['audio_url'] || triggerBody['recording'] || trigger['recording'] || "";

  // Dynamic Resolution of AI Coaching Note
  const aiCoachingNote = parsed.coaching_summary_note || parsed.coaching_reason || "";

  return {
    status: "completed",
    call_id: callId,
    duration: durationStr,
    language: parsed.language || "Unknown",
    audio_url: audioUrl,
    filename: filename, // returns clean filename without folder paths
    call_date: callDate || now.split('T')[0],
    kpi_score: kpiScore,
    sentiment: parsed.kpi15_customer_sentiment || "Neutral",
    sop_score: sopScore,
    agent_code: agentCode,
    agent_name: agentName,
    churn_risk: parsed.churn_risk || "None",
    created_at: now,
    call_intent: callTopic, // Dynamic resolved topic
    call_topic: callTopic, // Added at ROOT level for direct database mapping
    call_sub_topic: callSubTopic, // Added at ROOT level for direct database mapping
    kpi_results: JSON.stringify(kpiResultsArray),
    sop_results: JSON.stringify(sopResultsArray),
    call_summary: parsed.call_summary || "",
    intelligence: JSON.stringify({
      call_category: callCategory,
      call_topic: callTopic,
      call_sub_topic: callSubTopic,
      customer_type: parsed.customer_type || "Unknown",
      churn_risk: parsed.churn_risk || "None",
      coaching_priority: parsed.coaching_priority || "Green",
      coaching_summary_note: aiCoachingNote,
      compliance_risk: parsed.compliance_risk || "None",
      ztp_violation: parsed.ztp_violation || "No",
      probing_quality: parsed.probing_quality || "NA",
      empathy_score: parsed.empathy_score !== undefined ? parsed.empathy_score : 3,
      customer_pain_point: parsed.customer_pain_point || "",
      kpi11_secondary_intent: parsed.kpi11_secondary_intent || "None",
      // Naye BFSI Fields in Intelligence
      bfsi_false_guarantee_flag: parsed.bfsi_false_guarantee_flag || "No",
      bfsi_risk_disclaimer_spoken: parsed.bfsi_risk_disclaimer_spoken || "NA",
      bfsi_identity_verified: parsed.bfsi_identity_verified || "Yes",
      bfsi_product_category: parsed.bfsi_product_category || callTopic,
      bfsi_compliance_score: parsed.bfsi_compliance_score !== undefined ? parsed.bfsi_compliance_score : 100
    }),
    processed_at: now,
    coaching_note: aiCoachingNote, // Auto-mapped AI Coaching Note
    coaching_summary_note: aiCoachingNote,
    mobile_number: mobileNumber,
    quality_score: parsed.kpi6_call_quality_score || 3,
    ztp_violation: parsed.ztp_violation || "No",
    compliance_risk: parsed.compliance_risk || "None",
    recommendations: parsed.recommended_actions || "None",
    coaching_priority: parsed.coaching_priority || "Green",
    improvement_areas: parsed.improvement_areas || "None",
    cleaned_transcript: transcript,
    call_classification: callCategory,

    // Additional Naya Fields (Mapped directly)
    customer_type: parsed.customer_type || "Unknown",
    empathy_score: parsed.empathy_score !== undefined ? parsed.empathy_score : 3,
    probing_quality: parsed.probing_quality || "NA",
    customer_pain_point: parsed.customer_pain_point || "",

    // Naye BFSI Fields (Mapped directly at Root level)
    bfsi_false_guarantee_flag: parsed.bfsi_false_guarantee_flag || "No",
    bfsi_risk_disclaimer_spoken: parsed.bfsi_risk_disclaimer_spoken || "NA",
    bfsi_identity_verified: parsed.bfsi_identity_verified || "Yes",
    bfsi_product_category: parsed.bfsi_product_category || callTopic,
    bfsi_compliance_score: parsed.bfsi_compliance_score !== undefined ? parsed.bfsi_compliance_score : 100
  };
};
